// Confere o token enviado pelo site e monta o texto do aviso.
const TOKEN = 'COLE_AQUI_O_MESMO_VALOR_DE_N8N_WEBHOOK_TOKEN';
const item = $input.first().json;
const recebido = (item.headers || {})['x-webhook-token'] || '';
if (recebido !== TOKEN) { throw new Error('Token inválido: o aviso foi recusado'); }

const d = item.body || {};
let numero = String(d.whatsapp || '').replace(/\D/g, '');
if (numero.length === 10 || numero.length === 11) numero = '55' + numero;
const link = numero ? 'https://wa.me/' + numero : '(sem WhatsApp)';

let mensagem;
if (d.evento === 'atelie_pedido') {
  mensagem = [
    '🔔 Novo PEDIDO no Ateliê nº ' + d.numero,
    'Nome: ' + d.nome,
    'WhatsApp: ' + d.whatsapp,
    'Serviço: ' + d.servico,
    'Prazo: ' + (d.prazo || 'a combinar'),
    'Situação: ' + (d.descricao || '(não informou)'),
    'Responder: ' + link,
  ].join('\n');
} else if (d.evento === 'atelie_montador') {
  mensagem = [
    '🧰 Nova CANDIDATURA de montador nº ' + d.numero,
    'Nome: ' + d.nome,
    'WhatsApp: ' + d.whatsapp,
    'Setor: ' + d.setor,
    'Equipamento e tempo: ' + (d.disponibilidade || '(não informou)'),
    'Experiência: ' + (d.experiencia || '(não informou)'),
    'Responder: ' + link,
  ].join('\n');
} else {
  throw new Error('Evento desconhecido');
}

return [{ json: { mensagem, evento: d.evento, numero: d.numero, link } }];
